using System;
using System.IO;
using CheapLoc;
using Dalamud.Plugin;
using Dalamud.Plugin.Services;

namespace NekoDex;

/// <summary>
/// All user-visible text goes through <see cref="Get"/> so it can be localised. Keys are stable identifiers; the fallback is the English text.
/// Translations live in loc/{language}.json next to the plugin (CheapLoc format, generated by tools/LocExport); missing keys fall back to English.
/// </summary>
internal static class Strings
{
    public static string Get(string key, string fallback) => Loc.Localize(key, fallback);

    /// <summary>Loads the file for Dalamud's UI language, or English fallbacks when there is none.</summary>
    public static void Setup(IDalamudPluginInterface pluginInterface, IPluginLog log) => Apply(pluginInterface.UiLanguage, pluginInterface, log);

    public static void Apply(string language, IDalamudPluginInterface pluginInterface, IPluginLog log)
    {
        var assembly = typeof(Strings).Assembly;
        var directory = pluginInterface.AssemblyLocation.Directory?.FullName;
        var file = directory is null || string.IsNullOrEmpty(language) ? null : Path.Combine(directory, "loc", language + ".json");

        if (language != "en" && file is not null && File.Exists(file))
        {
            try
            {
                var json = File.ReadAllText(file);
                if (json.Trim().Length > 2)
                {
                    Loc.Setup(json, assembly);
                    log.Information("Loaded {Language} strings from {File}", language, file);
                    return;
                }
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                log.Warning(ex, "Could not read {File}; using English", file);
            }
        }

        Loc.SetupWithFallbacks(assembly);
    }
}
